/* True supervised partial fine-tuning of MobileNet V1 pw11 + a new 9-class head. */
const tf=require('@tensorflow/tfjs'),fs=require('fs'),os=require('os'),{loadModel,saveModel}=require('./model-io.cjs');
(async()=>{await tf.setBackend('cpu');const seed=5316,base=await loadModel('dist/model');base.trainable=false;const source=base.getLayer('conv_pw_11'),bnSource=base.getLayer('conv_pw_11_bn');const features=tf.model({inputs:base.inputs,outputs:base.getLayer('conv_dw_11_relu').output});const backbone=tf.model({inputs:base.inputs,outputs:base.getLayer('conv_pw_11_relu').output});
fs.mkdirSync('training-cache',{recursive:true});
async function cached(split){const raw=fs.readFileSync(`training-data/${split}.bin`),labels=JSON.parse(fs.readFileSync(`training-data/${split}-labels.json`));const file=`training-cache/${split}.json`;let data,shape;if(fs.existsSync(file)){({data,shape}=JSON.parse(fs.readFileSync(file)));}else{data=[];for(let i=0;i<labels.length;i+=16){const n=Math.min(16,labels.length-i);const f=tf.tidy(()=>features.predict(tf.image.resizeBilinear(tf.tensor4d(new Uint8Array(raw.buffer,raw.byteOffset+i*28*28*3,n*28*28*3),[n,28,28,3]),[64,64]).div(127.5).sub(1)));
shape=[labels.length,...f.shape.slice(1)];data.push(...await f.data());f.dispose();if(i%160===0)console.log('features',split,i,'/',labels.length);}fs.writeFileSync(file,JSON.stringify({data,shape}));}return{x:tf.tensor4d(data,shape),y:tf.tidy(()=>tf.oneHot(tf.tensor1d(labels,'int32'),9))};}
const train=await cached('train'),val=await cached('val'),test=await cached('test');
const input=tf.input({shape:train.x.shape.slice(1)}),conv=tf.layers.conv2d({...source.getConfig(),name:'finetune_pw11',trainable:true}),bn=tf.layers.batchNormalization({...bnSource.getConfig(),name:'frozen_bn11',trainable:false});let h=conv.apply(input);h=bn.apply(h);h=tf.layers.reLU({maxValue:6}).apply(h);h=tf.layers.globalAveragePooling2d({}).apply(h);const output=tf.layers.dense({units:9,activation:'softmax',kernelInitializer:tf.initializers.glorotUniform({seed}),biasInitializer:'zeros',name:'tissue_classifier'}).apply(h);const classifier=tf.model({inputs:input,outputs:output});conv.setWeights(source.getWeights());bn.setWeights(bnSource.getWeights());classifier.compile({optimizer:tf.train.adam(.001),loss:'categoricalCrossentropy',metrics:['accuracy']});
const run={id:'pathmnist-pilot-v1',codeVersion:'prd2-engine-v1',datasetId:'pathmnist-28-subset-seed5316',seed,startedAt:new Date().toISOString(),device:`${os.cpus()[0].model} / ${os.arch()} / TFJS CPU`,architecture:'MobileNet V1 width 0.25',objective:'9-class tissue classification / categorical cross-entropy',trainingType:'partial fine-tuning: conv_pw_11 + new dense classifier; all earlier layers and batch normalization frozen',epochs:8,batchSize:30,learningRate:.001,inputSize:64,shuffle:false,logs:[],checkpoints:[],test:null};
async function metric(data){const scores=classifier.evaluate(data.x,data.y,{batchSize:30});const values=await Promise.all(scores.map(t=>t.data()));scores.forEach(t=>t.dispose());return{loss:values[0][0],accuracy:values[1][0]};}
async function checkpoint(epoch){source.setWeights(conv.getWeights());const dir=`dist/training/checkpoints/epoch-${epoch}`;const info=await saveModel(backbone,dir);await saveModel(classifier,`${dir}/classifier`);run.checkpoints.push({id:`pathmnist-pilot-epoch-${epoch}`,epoch,url:`training/checkpoints/epoch-${epoch}/model.json`,...info});}
function log(){fs.writeFileSync('dist/training/run.json',JSON.stringify(run,null,2));}
const baselineTrain=await metric(train),baselineVal=await metric(val);run.logs.push({epoch:0,step:0,trainLoss:baselineTrain.loss,trainAccuracy:baselineTrain.accuracy,valLoss:baselineVal.loss,valAccuracy:baselineVal.accuracy});await checkpoint(0);log();console.log('epoch0',run.logs.at(-1));
for(let epoch=1;epoch<=8;epoch++){const started=Date.now();await classifier.fit(train.x,train.y,{epochs:1,batchSize:30,shuffle:false,verbose:0});const tr=await metric(train),v=await metric(val);run.logs.push({epoch,step:epoch*30,trainLoss:tr.loss,trainAccuracy:tr.accuracy,valLoss:v.loss,valAccuracy:v.accuracy,elapsedMs:Date.now()-started});if([2,4,8].includes(epoch))await checkpoint(epoch);log();console.log('epoch',epoch,JSON.stringify(run.logs.at(-1)));}
run.test=await metric(test);run.completedAt=new Date().toISOString();log();console.log('COMPLETE test',run.test);
})().catch(e=>{console.error(e);process.exit(1)});
